queries.sql:
SELECT status, count(*) AS row_count
FROM {schema}.exception_queue_{stream_id}
WHERE consumer_group_id = {group_id}
GROUP BY status;

SELECT
	message_id,
	attempts,
	last_error,
	updated_at
FROM {schema}.exception_queue_{stream_id}
WHERE consumer_group_id = {group_id}
	AND status = 'dead'
ORDER BY message_id;

SELECT
	message_id,
	status,
	attempts,
	updated_at
FROM {schema}.exception_queue_{stream_id}
WHERE consumer_group_id = {group_id}
ORDER BY updated_at DESC
LIMIT 20;

SELECT
	token,
	low,
	high,
	expires_at,
	reclaims
FROM {schema}.claim_lease_{stream_id}
WHERE consumer_group_id = {group_id}
ORDER BY low;

SELECT
	message_id,
	status,
	attempts,
	last_error
FROM {schema}.exception_queue_{stream_id}
WHERE consumer_group_id = {group_id}
	AND message_id BETWEEN {low} AND {high}
ORDER BY message_id;

SELECT
	message_id,
